#!/bin/bash
sed -i -e '/let headColor = 0x888888;/!b' -e '/const headMat = new THREE.MeshLambertMaterial({ color: headColor });/!b' -e 's/let headColor = 0x888888;/let headColor = 0x888888;\n      let roughness = 0.6;\n      let metalness = 0.3;\n      let emissive = 0x000000;\n      let emissiveIntensity = 0.0;\n\n      if (item.itemId.includes("wood")) {\n        headColor = 0x8b5a2b;\n        roughness = 0.9;\n        metalness = 0.0;\n      } else if (item.itemId.includes("copper")) {\n        headColor = 0xc87d55;\n        roughness = 0.45;\n        metalness = 0.6;\n      } else if (item.itemId.includes("iron")) {\n        headColor = 0xdcdcdc;\n        roughness = 0.35;\n        metalness = 0.75;\n      } else if (item.itemId.includes("gold")) {\n        headColor = 0xfacc15;\n        roughness = 0.25;\n        metalness = 0.85;\n      } else if (item.itemId.includes("mythril")) {\n        headColor = 0x88ccff;\n        roughness = 0.2;\n        metalness = 0.9;\n      } else if (item.itemId.includes("aether")) {\n        headColor = 0xc084fc;\n        roughness = 0.4;\n        metalness = 0.5;\n        emissive = 0x5511aa;\n        emissiveIntensity = 0.5;\n      }/' src/engine/player/FirstPersonViewmodel.ts
